#include <stdio.h>
#include <stdlib.h>

// Kruskal's algorithm to find the Minimum Spanning Tree of a graph
void kruskal(int *edge_a, int *edge_b, int *edge_w, int num_edges, int num_vertices) {
    int *parent = (int *)malloc(num_vertices * sizeof(int));
    for (int i = 0; i < num_vertices; i++) {
        parent[i] = i;
    }

    int num_mst_edges = 0;
    int mst_weight = 0;
    printf("weight=%d edges=", mst_weight);

    for (int i = 0; i < num_edges; i++) {
        int vertex_a = edge_a[i];
        int vertex_b = edge_b[i];
        int weight = edge_w[i];

        if (find(parent, vertex_a) != find(parent, vertex_b)) {
            union_set(parent, vertex_a, vertex_b);
            mst_weight += weight;
            num_mst_edges++;
            printf("%d-%d", vertex_a, vertex_b);
            if (num_mst_edges < num_vertices - 1) {
                printf(",");
            }
        }
    }
    printf("\n");
}

int find(int *parent, int vertex) {
    if (parent[vertex] == vertex) {
        return vertex;
    }
    return find(parent, parent[vertex]);
}

void union_set(int *parent, int vertex_a, int vertex_b) {
    int root_a = find(parent, vertex_a);
    int root_b = find(parent, vertex_b);
    parent[root_a] = root_b;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <number_of_vertices>\n", argv[0]);
        return 1;
    }

    int num_vertices = atoi(argv[1]);
    int num_edges = (num_vertices * (num_vertices - 1)) / 2;
    int *edge_a = (int *)malloc(num_edges * sizeof(int));
    int *edge_b = (int *)malloc(num_edges * sizeof(int));
    int *edge_w = (int *)malloc(num_edges * sizeof(int));

    // Initialize the edges
    int edge_index = 0;
    for (int i = 0; i < num_vertices; i++) {
        for (int j = i + 1; j < num_vertices; j++) {
            edge_a[edge_index] = i;
            edge_b[edge_index] = j;
            edge_w[edge_index] = 1; // Assign a weight of 1 to each edge for simplicity
            edge_index++;
        }
    }

    kruskal(edge_a, edge_b, edge_w, num_edges, num_vertices);

    free(edge_a);
    free(edge_b);
    free(edge_w);

    return 0;
}
